prts.feedbackvariables:
matrixInput: is(delete(true,map(matrixp,ans1)) = []);
isSquare(M):= is(length(M) = dm and length(M[1]) = dm);
validInput: if (matrixInput) then is(delete(true,map(isSquare,ans1))=[]) else false;
isEl: if (validInput) then is(delete(true,map(isElementary,ans1))=[]) else false;

multipliedAns: if isEl then lreduce(lambda([x,y],x.y),ans1,ident(dm)) else "Invalid Input err";
